"// Please enter the mapping logic to generate the Lastname.
function getLastName() {
    let middleName = Person.Name.FamilyNamePrefix;
    let lastName = Person.Name.FamilyName;
    let middleNamePartner = Person.Name.FamilyNamePartnerPrefix;
    let lastNamePartner = Person.Name.FamilyNamePartner;
    let convention = Person.Name.Convention;

    let nameFormatted = '';
    let sureName = ''

    switch (convention) {
        case "BP":
            nameFormatted = lastName + ' - ';
            if (typeof middleNamePartner !== 'undefined' && middleNamePartner) { nameFormatted = nameFormatted + middleNamePartner + ' ' }
            nameFormatted = nameFormatted + lastNamePartner;
            break;
        case "P":
            nameFormatted = lastNamePartner;
            break;
        case "PB":
            nameFormatted = lastNamePartner + ' - ';
            if (typeof middleName !== 'undefined' && middleName) { nameFormatted = nameFormatted + middleName + ' ' }
            nameFormatted = nameFormatted + lastName;
            break;
        case "B":
        default:
            nameFormatted = lastName;
            break;
    }

    if (typeof nameFormatted !== 'undefined' && nameFormatted) {
        sureName = nameFormatted.trim();
    } else {
        sureName = nameFormatted;
    }

    return sureName;
}

getLastName();"

"function getPrefixes() {
    let middleName = Person.Name.FamilyNamePrefix;
    let middleNamePartner = Person.Name.FamilyNamePartnerPrefix;
    let convention = Person.Name.Convention;

    let nameFormatted = '';
    let prefix = '';

    switch (convention) {
        case "P":
        case "PB":
            nameFormatted = middleNamePartner;
            break;
        case "B":
        case "BP":
        default:
            nameFormatted = middleName;
            break;
    }

    if (typeof nameFormatted !== 'undefined' && nameFormatted) {
        prefix = nameFormatted.trim();
    } else {
        prefix = null;
    }

    return prefix;
}

getPrefixes();"

"function convertDate(date) {
    // Get day, month, and year components
    const day = date.getDate().toString().padStart(2, '0');
    const month = (date.getMonth() + 1).toString().padStart(2, '0');
    const year = date.getFullYear();

    // Format the date as "dd-mm-yyyy"
    return year + '-' + month + '-' + day;
}

function getHireDate(){
    let inputDate = Person.PrimaryContract.StartDate
    let returnDate = inputDate ? convertDate(new Date(inputDate)) : null;

    return returnDate;
}

getHireDate();"

